SINA_SMART["physio1-heart"] = {"lecture":"physio1-heart","title":"Physiology of the heart","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"physio1-heart:e0","text":"Wall: epicardium, myocardium, endocardium; 2 AV + 2 semilunar valves.","topic":"Structure of the heart","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-heart:e1","text":"~1% of cardiomyocytes renewed per year → infarcts are permanent.","topic":"Structure of the heart","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-heart:e2","text":"Conduction: SA → internodal → AV (0.1 s delay) → His → branches → Purkinje.","topic":"Conduction system and pacemaker","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-heart:e3","text":"Intrinsic rates: SA ~70, AV ~50, Purkinje ~30/min.","topic":"Conduction system and pacemaker","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-heart:e4","text":"Pacemaker potential: funny current I_f + T-type Ca²⁺ channels.","topic":"Conduction system and pacemaker","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-heart:e5","text":"Gap junctions link conducting and contractile cells.","topic":"Conduction system and pacemaker","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-heart:e9","text":"Pacemakers replace a failing conduction system.","topic":"Conduction system and pacemaker","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-heart:e6","text":"Sympathetic NE on β1: ↑ rate and force; vagal ACh on muscarinic receptors: ↓ rate.","topic":"Nerves and hormones","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-heart:e7","text":"Atria secrete ANP → natriuresis.","topic":"Nerves and hormones","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"physio1-heart:e8","text":"Atrial fibrillation: poor filling, clots; ventricular fibrillation: cardiac arrest → defibrillation.","topic":"Arrhythmias","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"dz49st":"a","1r9w70k":"a","32rrto":"a","ikmton":"a","16i5j9d":"a","141nb5c":"a","1ti3cmy":"a","1uhygzm":"a","13nis35":"a","m3cqto":"a","zct8z":"a","2kkwsx":"a","kjjo6n":"a","1146li8":"a","4v3lh8":"a"},"mapCounts":{"verified":0,"auto":15,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"physio1-heart:e0":{"s":0,"u":["Wall: epicardium, myocardium, endocardium; 2 AV + 2 semilunar valves.","Four valves ensure one-way flow: two atrioventricular valves (tricuspid, mitral) between atria and ventricles and two semilunar valves (pulmonary, aortic) at the ventricular outlets.","The heart wall has three layers: the epicardium (outer, the visceral layer of the serous pericardium), the myocardium (cardiac muscle, the bulk of the heart, the layer that contracts) and the endocardium (endothelium on thin connective tissue, continuous with the vessel lining)."],"dp":[]},"physio1-heart:e1":{"s":0,"u":["~1% of cardiomyocytes renewed per year → infarcts are permanent.","Regeneration is very limited (about 1% of cardiomyocytes replaced per year ), which is why myocardial infarction leaves permanent damage."],"dp":[]},"physio1-heart:e2":{"s":1,"u":["Conduction: SA → internodal → AV (0.1 s delay) → His → branches → Purkinje.","They have automaticity : the sinoatrial (SA) node (normal pacemaker, about 70/min ), the internodal pathways, the atrioventricular (AV) node (delays the impulse by about 0.1 s so the atria fill the ventricles), the bundle of His , the bundle branches and the Purkinje fibres , which run to the apex, then turn upward through the ventricles and reach the papillary muscles so they tense before the ventricular walls contract."],"dp":[]},"physio1-heart:e3":{"s":1,"u":["Intrinsic rates: SA ~70, AV ~50, Purkinje ~30/min.","If a higher pacemaker fails, a lower one takes over at its own slower rate: AV node about 50/min , Purkinje about 30/min ."],"dp":[{"h":"Why the heart has a built-in backup","t":"Every cell of the conducting system can generate impulses, but the fastest one sets the rhythm and keeps the slower ones reset before they fire (overdrive suppression). If the SA node fails, the AV node takes over at about 50/min; if conduction through the AV node is blocked, the ventricles still beat at about 30/min from Purkinje fibres. This backup keeps a person alive in complete heart block, though the slow rate causes fatigue and fainting, which is exactly the situation an implanted pacemaker corrects. Source: the lecture's SA/AV/Purkinje rate diagrams and pacemaker slide."}]},"physio1-heart:e4":{"s":1,"u":["Pacemaker potential: funny current I_f + T-type Ca²⁺ channels.","The pacemaker potential of SA cells is a slow spontaneous depolarisation due to the 'funny' current I f (Na⁺ inward current activated by hyperpolarisation) and T-type Ca²⁺ channels , followed by an action potential."],"dp":[]},"physio1-heart:e5":{"s":1,"u":["Gap junctions link conducting and contractile cells.","About 1% of cardiac cells are not contractile but form the conducting system , linked to the myocardium by gap junctions .","Contractile cells have a long plateau action potential."],"dp":[]},"physio1-heart:e9":{"s":1,"u":["Pacemakers replace a failing conduction system."],"dp":[]},"physio1-heart:e6":{"s":2,"u":["Sympathetic NE on β1: ↑ rate and force; vagal ACh on muscarinic receptors: ↓ rate.","Parasympathetic (vagal) fibres innervate mainly the nodes and release acetylcholine on muscarinic receptors: slower rate.","Sympathetic fibres innervate the whole heart (nodes and muscle) and release noradrenaline on mainly β-adrenergic (β1) receptors; adrenaline from the adrenal medulla acts on the same receptors: faster rate and stronger contraction."],"dp":[]},"physio1-heart:e7":{"s":2,"u":["Atria secrete ANP → natriuresis.","The heart is also an endocrine organ: atrial cells secrete atrial natriuretic peptide (ANP) when stretched, promoting Na⁺ excretion and regulating extracellular Na⁺ and volume."],"dp":[]},"physio1-heart:e8":{"s":3,"u":["Atrial fibrillation: poor filling, clots; ventricular fibrillation: cardiac arrest → defibrillation.","Atrial fibrillation impairs ventricular filling and promotes clots (stroke risk).","Ventricular fibrillation is life-threatening: the ventricles do not pump, circulation stops and brain death follows unless defibrillation , an electric shock, restores sinus rhythm."],"dp":[]}},"meta":{"dz49st":{"a":"recall","vg":"physio1-heart:e0/recall/1"},"1r9w70k":{"a":"recall","vg":"physio1-heart:e0/recall/2"},"32rrto":{"a":"recall","vg":"physio1-heart:e2/recall/1"},"ikmton":{"a":"recall","vg":"physio1-heart:e2/recall/2"},"16i5j9d":{"a":"application","vg":"physio1-heart:e3/application/1"},"141nb5c":{"a":"recall","vg":"physio1-heart:e4/recall/1"},"1ti3cmy":{"a":"recall","vg":"physio1-heart:e5/recall/1"},"1uhygzm":{"a":"recall","vg":"physio1-heart:e6/recall/1"},"13nis35":{"a":"recall","vg":"physio1-heart:e6/recall/1"},"m3cqto":{"a":"recall","vg":"physio1-heart:e6/recall/2"},"zct8z":{"a":"recall","vg":"physio1-heart:e7/recall/1"},"2kkwsx":{"a":"recall","vg":"physio1-heart:e7/recall/2"},"kjjo6n":{"a":"recall","vg":"physio1-heart:e8/recall/1"},"1146li8":{"a":"recall","vg":"physio1-heart:e8/recall/2"},"4v3lh8":{"a":"recall","vg":"physio1-heart:e1/recall/1"}},"explRev":"79ec498d86c1"};
